    TwistExpander_Saiph_Arx::KEY_A_D_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(SAIPH_KEY_A_D_IceLaneA, SAIPH_KEY_A_D_IceLaneB, SAIPH_KEY_A_D_IceLaneC, SAIPH_KEY_A_D_IceLaneD, &(pWorkSpace->mKeyBoxA[3U][0]));

